package bookstore

// Cost returns the total price, in cents, of the books in the basket,
// applying the largest possible discount.
//
// The five books are grouped into sets of distinct titles. A set of n
// different books costs:
//
//	1 book: 800 (no discount)
//	2 books: 5% off  -> 2 x 760 = 1520
//	3 books: 10% off -> 3 x 720 = 2160
//	4 books: 20% off -> 4 x 640 = 2560
//	5 books: 25% off -> 5 x 600 = 3000
//
// The cheapest grouping is formed "layer by layer": each layer takes one
// copy of every title that still has copies left. This yields the most
// even distribution of group sizes, which minimizes the total because
// larger groups of distinct titles have a lower per-book price.
//
// One exception: a 5-group next to a 3-group (3000 + 2160 = 5160) is
// cheaper split into two 4-groups (2 x 2560 = 5120), saving 40 cents
// per such pair. So the number of 5-groups and 3-groups are paired off
// and each pair is converted into two 4-groups.
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		counts[b-1]++
	}

	// Price in cents of a group of n different books.
	groupPrice := [6]int{0, 800, 1520, 2160, 2560, 3000}

	total := 0
	fives, threes := 0, 0
	for layer := 0; ; layer++ {
		// One group per layer: one copy of each title with more
		// than `layer` copies remaining.
		n := 0
		for i := 0; i < 5; i++ {
			if counts[i] > layer {
				n++
			}
		}
		if n == 0 {
			break
		}
		total += groupPrice[n]
		switch n {
		case 5:
			fives++
		case 3:
			threes++
		}
	}

	// Each 5-group/3-group pair is cheaper as two 4-groups.
	if fives < threes {
		total -= 40 * fives
	} else {
		total -= 40 * threes
	}
	return total
}
